import{_ as r,o as a,c as d,a0 as o}from"./chunks/framework.Czf8PZMA.js";const u=JSON.parse('{"title":"SECTION 13 34 23 — Fabricated Structure: UHPC（预制 UHPC 结构模块）★可直接投用完整条款版★","description":"","frontmatter":{},"headers":[],"relativePath":"guide/08-section-uhpc.md","filePath":"guide/08-section-uhpc.md","lastUpdated":null}'),e={name:"guide/08-section-uhpc.md"};function l(i,t,n,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="section-13-34-23-—-fabricated-structure-uhpc-预制-uhpc-结构模块-★可直接投用完整条款版★" tabindex="-1">SECTION 13 34 23 — Fabricated Structure: UHPC（预制 UHPC 结构模块）★可直接投用完整条款版★ <a class="header-anchor" href="#section-13-34-23-—-fabricated-structure-uhpc-预制-uhpc-结构模块-★可直接投用完整条款版★" aria-label="Permalink to &quot;SECTION 13 34 23 — Fabricated Structure: UHPC（预制 UHPC 结构模块）★可直接投用完整条款版★&quot;">​</a></h1><blockquote><p>📌 <strong>本文件是把 <code>03_混凝土UHPC框架</code> 的「13 34 23」展开成可投用的 MasterFormat 三段式完整条款</strong> （Part 1 General / Part 2 Products / Part 3 Execution），内嵌<strong>中美标准对应</strong>与<strong>合规流程停点</strong>。</p><ul><li>用法：复制进项目 SPEC，填 <code>[待定]</code> 处即可发出；Part 2/3 验收项可进采购/合同。</li><li>依据：UHPC docx（权威 Gate1-6）+ <code>01_共享框架</code> §0.4 + <code>06_材料清单</code> §0.0 中美对应 + spec-agent 模板。</li><li>代码：MasterFormat 13 34 23 — Fabricated Structures（预制结构）。</li></ul></blockquote><hr><h2 id="part-1-—-general-一般要求" tabindex="-1">PART 1 — GENERAL（一般要求） <a class="header-anchor" href="#part-1-—-general-一般要求" aria-label="Permalink to &quot;PART 1 — GENERAL（一般要求）&quot;">​</a></h2><h3 id="_1-1-章节范围" tabindex="-1">1.1 章节范围 <a class="header-anchor" href="#_1-1-章节范围" aria-label="Permalink to &quot;1.1 章节范围&quot;">​</a></h3><ul><li><strong>UHPC（超高性能混凝土）模块壳体与预制结构构件</strong>之委派设计、配比、模具、制造、养护、运输保护、现场就位与连接。</li><li>UHPC 壳体之配筋/纤维、预埋件（吊点/连接板/管线套管/封边型钢）、节点（连接板焊/栓、销轴、耗能连接）。</li><li>横向关联：Division 01 33（提交）/01 43（QA）/01 45（QC）/01 66（吊装）、03 30（基础锚栓）、07 25/27/62（缝水密气密）、07 84（防火封堵）、13 42 00（模块本体）、13 48（抗震连接）。</li></ul><h3 id="_1-2-引用文件" tabindex="-1">1.2 引用文件 <a class="header-anchor" href="#_1-2-引用文件" aria-label="Permalink to &quot;1.2 引用文件&quot;">​</a></h3><ul><li><strong>ESR-5874</strong>（UHPC 系统评估报告：允许应力、配合比、纤维类型/掺量、水胶比、构件尺寸、配筋、节点、耐火构造、连接方式、安装限制）；<strong>ESR 适用矩阵逐项映射到本项目</strong> ⭐核心</li><li><strong>ACI 318 / ACI 533R</strong>（混凝土模块设计指南）/ <strong>ACI 551R</strong>（薄壳）/ <strong>ACI ITG / PCI Design Handbook</strong>（预制/预应力）</li><li><strong>ASTM C150/C618/C1240</strong>（胶凝材料）、<strong>ASTM C1876</strong>（UHPC 拉伸）、<strong>ASTM C1856</strong>（UHPC 试验）、<strong>ASTM C39/C143</strong>（强度/坍落度）</li><li><strong>ACI 355</strong>（后锚固化学锚栓，与混凝土模块间钢平台连接时）</li><li>加州/联邦：<strong>CBC（Title 24 Part 2）+ ASCE 7</strong>（抗震）、<strong>HCD Title 25 §3032</strong>（检率）、<strong>HSC §19980</strong>（insignia）、<strong>ACI 117</strong>（容差）</li><li>中美对应：<strong>GB 50010</strong>（砼规范）、<strong>GB/T 50107</strong>（强度验评）、<strong>GB 175</strong>（水泥）、<strong>GB/T 14684/14685</strong>（骨料）、<strong>GB/T 8076</strong>（外加剂）、UHPC 对标 <strong>T/CECS 1130 / GB/T 17671</strong> ——详见 2.1。</li></ul><h3 id="_1-3-提交要求" tabindex="-1">1.3 提交要求 <a class="header-anchor" href="#_1-3-提交要求" aria-label="Permalink to &quot;1.3 提交要求&quot;">​</a></h3><ul><li>UHPC <strong>配合比设计 + 试件强度曲线</strong>；纤维/胶凝/减水剂品牌与 ESR-5874 一致声明。</li><li>委托设计计算书 + 加州执照 SE 复核签字（DAA 版=现场版）。</li><li><strong>首件模块（first article）报告</strong> + ITP/检验试验计划 + FAT 清单。</li><li>预埋件材质/定位图、吊装方案（重心/平衡梁）、运输保护措施。</li><li>养护记录（蒸汽/密封）、尺寸偏差报告、强度（试件）报告。</li></ul><h3 id="_1-4-质量保证-qa" tabindex="-1">1.4 质量保证（QA） <a class="header-anchor" href="#_1-4-质量保证-qa" aria-label="Permalink to &quot;1.4 质量保证（QA）&quot;">​</a></h3><ul><li>工厂 QAA 第三方检验；检率依 Title 25 §3032（新型号100%→首10台全检→可降25%）。</li><li><strong>首件模块重点验证</strong>：模块接口、水密、耐火封堵、抗震连接、设备检修空间、运输/吊装保护（权威：UHPC docx）。</li></ul><h3 id="_1-5-交货存储" tabindex="-1">1.5 交货存储 <a class="header-anchor" href="#_1-5-交货存储" aria-label="Permalink to &quot;1.5 交货存储&quot;">​</a></h3><ul><li>运输按 01 66 + Caltrans 限重；UHPC 模块重，需专用低平板+护角+临时撑杆；到货裂纹/缺角如实记录、NCR 关闭后方可安装。</li></ul><hr><h2 id="part-2-—-products-产品-材料" tabindex="-1">PART 2 — PRODUCTS（产品/材料） <a class="header-anchor" href="#part-2-—-products-产品-材料" aria-label="Permalink to &quot;PART 2 — PRODUCTS（产品/材料）&quot;">​</a></h2><h3 id="_2-1-中美材料换算表-写入采购-★" tabindex="-1">2.1 中美材料换算表（写入采购）★ <a class="header-anchor" href="#_2-1-中美材料换算表-写入采购-★" aria-label="Permalink to &quot;2.1 中美材料换算表（写入采购）★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部位</th><th>美国标准（验收基准）</th><th>中国对应规范</th><th>差异处理</th></tr></thead><tbody><tr><td>UHPC 系统评定</td><td><strong>ESR-5874</strong>（允许应力/配比/纤维/水胶比/耐火）</td><td>T/CECS 1130、GB/T 17671</td><td>ESR=验收；中标配合比内部参考，逐项映射适用矩阵</td></tr><tr><td>胶凝材料（水泥）</td><td>ASTM C150/C618/C1240</td><td><strong>GB 175</strong>、GB/T 18046</td><td>强度等级/化学组成对标</td></tr><tr><td>骨料</td><td>ASTM C33</td><td><strong>GB/T 14684/14685</strong></td><td>级配/含泥量验收</td></tr><tr><td>外加剂（减水/引气）</td><td>ASTM C494</td><td><strong>GB/T 8076</strong></td><td>减水率/凝结时间对标</td></tr><tr><td>纤维（钢/合成）</td><td>按 ESR-5874 类型/掺量</td><td>国标钢纤维/YB 或对标</td><td>抗拉/分散性按 ESR</td></tr><tr><td>混凝土设计</td><td>ACI 318 + ESR</td><td><strong>GB 50010</strong></td><td>加州以 ACI/CBC 为准</td></tr><tr><td>锚栓/预埋</td><td>ACI 117 容差、ACI 355 后锚固</td><td>GB/T 798/799、GB 50010</td><td>定位±2mm、化学锚栓对标</td></tr></tbody></table><h3 id="_2-2-材料构件" tabindex="-1">2.2 材料构件 <a class="header-anchor" href="#_2-2-材料构件" aria-label="Permalink to &quot;2.2 材料构件&quot;">​</a></h3><ul><li><strong>UHPC 基体</strong>：配合比依 ESR-5874（胶凝/纤维/水胶比/砂硅灰）；强度等级、弹性模量、收缩/徐变、抗渗、冻融依 ESR 与 CBC 定。</li><li><strong>配筋/纤维</strong>：钢筋按 ACI 318（配筋），纤维（钢/合成）增韧按 ESR；绑扎/保护层厚度。</li><li><strong>预埋件</strong>：吊点、连接板、管线套管、封边型钢；材质与定位按图。</li><li><strong>模具/表面</strong>：模具表面质量、脱模剂，支持装饰/清水/薄壳要求（ACI 551）。</li></ul><h3 id="_2-3-节点材料" tabindex="-1">2.3 节点材料 <a class="header-anchor" href="#_2-3-节点材料" aria-label="Permalink to &quot;2.3 节点材料&quot;">​</a></h3><ul><li>模块间结构连接：预埋连接板+焊接/螺栓、销轴、耗能连接（抗震）；后锚固化学锚栓（ACI 355，与钢平台连接时）。</li><li>接缝密封胶/背衬（ASTM C920）、防火封堵系统（UL 1479）随装配交付。</li></ul><hr><h2 id="part-3-—-execution-安装与执行" tabindex="-1">PART 3 — EXECUTION（安装与执行） <a class="header-anchor" href="#part-3-—-execution-安装与执行" aria-label="Permalink to &quot;PART 3 — EXECUTION（安装与执行）&quot;">​</a></h2><h3 id="_3-1-工厂制造与出厂-fc-段" tabindex="-1">3.1 工厂制造与出厂（FC 段） <a class="header-anchor" href="#_3-1-工厂制造与出厂-fc-段" aria-label="Permalink to &quot;3.1 工厂制造与出厂（FC 段）&quot;">​</a></h3><ul><li>模具组装→浇筑/振动→养护（蒸汽/密封）→拆模→预埋件校核→尺寸公差全检→表面质量→<strong>首件验证全公差链</strong>→FAT→运输加固。</li><li>出厂停点：配合比证、强度（试件）、尺寸偏差、表面、预埋定位、FAT 通过。</li></ul><h3 id="_3-2-吊装与就位-现场段" tabindex="-1">3.2 吊装与就位（现场段） <a class="header-anchor" href="#_3-2-吊装与就位-现场段" aria-label="Permalink to &quot;3.2 吊装与就位（现场段）&quot;">​</a></h3><ul><li><strong>吊点/重心/平衡梁经结构工程师</strong>；禁止非批准吊点；吊装顺序与临时支撑对齐 01 66。</li><li>起重按 ASME B30.5 + OSHA 1926；UHPC 重构件需专用吊具与防倾覆。</li></ul><h3 id="_3-3-模块间连接执行" tabindex="-1">3.3 模块间连接执行 <a class="header-anchor" href="#_3-3-模块间连接执行" aria-label="Permalink to &quot;3.3 模块间连接执行&quot;">​</a></h3><ul><li>结构连接（预埋连接板焊/栓、销轴、耗能）→ 接缝密封/背衬（水密气密 07 25/27）→ 封边泛水（07 62）→ <strong>防火封堵（07 84）</strong> → 隐蔽前验收。</li><li>现场就位容差 + <strong>累积容差</strong>控制；接缝密封胶/背衬养护。</li></ul><h3 id="_3-4-检验与停点-hold-points-★★★★" tabindex="-1">3.4 检验与停点（Hold Points）★★★★ <a class="header-anchor" href="#_3-4-检验与停点-hold-points-★★★★" aria-label="Permalink to &quot;3.4 检验与停点（Hold Points）★★★★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>停点</th><th>时机</th><th>验收项</th><th>放行</th></tr></thead><tbody><tr><td><strong>HP-1</strong></td><td>出厂前</td><td>配合比/强度/尺寸/预埋/FAT + insignia</td><td>工厂 QAA 签 + insignia</td></tr><tr><td><strong>HP-2</strong></td><td>现场就位前</td><td>基础交接、锚栓复核（±2mm）、吊装方案</td><td>现场验收单</td></tr><tr><td><strong>HP-3</strong></td><td>连接后/隐蔽前</td><td>节点焊/栓检、水密、耐火封堵、抗震连接、NDT</td><td>NCR 关闭 + 三重放行</td></tr></tbody></table><ul><li><strong>ESR 适用矩阵</strong>：每个装配体/构件逐项核对 ESR-5874 限值（允许应力、耐火极限、连接、安装限制）。</li><li>检验嵌入 Gate 1-6：HP-1↔Gate 4，HP-2/3↔Gate 5。</li></ul><h3 id="_3-5-现场清理保护" tabindex="-1">3.5 现场清理保护 <a class="header-anchor" href="#_3-5-现场清理保护" aria-label="Permalink to &quot;3.5 现场清理保护&quot;">​</a></h3><ul><li>清理浇筑渣/密封溢出；补涂节点界面；表面缺陷（裂纹/缺角）NCR 关闭后放行。</li></ul><hr><h2 id="验收汇总表-可进合同" tabindex="-1">验收汇总表（可进合同） <a class="header-anchor" href="#验收汇总表-可进合同" aria-label="Permalink to &quot;验收汇总表（可进合同）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>性能/验收要求</th><th>标准</th></tr></thead><tbody><tr><td>UHPC 强度/配比</td><td>按 ESR-5874 适用矩阵</td><td>ESR-5874</td></tr><tr><td>UHPC 拉伸</td><td>按 ASTM C1876</td><td>ASTM C1876</td></tr><tr><td>预埋件定位</td><td>中心线 ≤±2mm</td><td>ACI 117</td></tr><tr><td>检验频率</td><td>新型号100%→首10台→25%（可降）</td><td>HCD Title 25 §3032</td></tr><tr><td>出厂放行</td><td>insignia + 三重放行</td><td>HSC §19980 + 01 45</td></tr><tr><td>后锚固（适用）</td><td>ACI 355 化学锚栓</td><td>ACI 355</td></tr></tbody></table><hr><p><em>本完整 SECTION 由 Modular-Agent 依据 UHPC docx（权威）+ spec-agent 模板 + <code>01_共享框架</code> §0.4 编制；Part 2 中美对应内嵌中国工厂对标需求。入口与流程见 <code>00_操作手册总纲</code>。</em></p>',40)])])}const C=r(e,[["render",l]]);export{u as __pageData,C as default};
